create table if not exists public.buildpulse_house_ads(id uuid primary key default gen_random_uuid(),campaign_code text not null unique,brand text not null,headline text not null,copy_text text,destination_url text not null,creative_url text,creative_asset_ref text,creative_width integer,creative_height integer,placement text not null default 'homepage',status text not null default 'asset_pending' check(status in('asset_pending','scheduled','active','paused','completed')),disclosure text not null default 'Advertisement',priority integer not null default 100,starts_at timestamptz,ends_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),metadata jsonb not null default '{}'::jsonb);alter table public.buildpulse_house_ads enable row level security;revoke all on public.buildpulse_house_ads from anon,authenticated;grant all on public.buildpulse_house_ads to service_role;create index if not exists idx_buildpulse_house_ads_live on public.buildpulse_house_ads(placement,status,priority desc);